items.referenceSolution:
#include <iostream>
#include <bitset>
using namespace std;

int main() {
    int n = 0;
    unsigned int x = 0;
    cin >> n;
    cin >> x;
    unsigned int flipped = x ^ (1u << n);
    cout << x << " 的格子是 " << bitset<8>(x)
         << "，翻第 " << n << " 格之后是 " << bitset<8>(flipped) << endl;
    return 0;
}

